protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // HasIndex throws at startup in EF Core 9 Cosmos — manage indexing
    // via the Azure Portal or Bicep/Terraform indexing policy instead.

    modelBuilder.Entity<Product>().ToContainer("Products");

    // EF Core 9 changed the default discriminator property from "Discriminator"
    // to "$type". Preserve the old name so existing documents remain queryable
    // and direct SQL queries (WHERE c.Discriminator = ...) keep working.
    modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

    // EF Core 9 no longer includes the discriminator in the JSON id property.
    // Existing documents use "Product|123" format — keep generating that format
    // so FindAsync/point-reads work against the 500K existing documents.
    modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);
}

